 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Each pair of 7s on the same row/column marks a straight segment; color
    # cells along that segment between them with 3, preserving endpoint 7s.
    pts = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    for i, (r1,c1) in enumerate(pts):
        for r2,c2 in pts[i+1:]:
            dr, dc = r2-r1, c2-c1
            if dr == 0 or dc == 0:
                n = max(abs(dr), abs(dc))
                sr = 0 if dr == 0 else dr//n
                sc = 0 if dc == 0 else dc//n
                for k in range(1,n):
                    r,c = r1+sr*k, c1+sc*k
                    if grid[r][c] == 5:
                        out[r][c] = 3
    return out
