 "content": "def transform(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    marker = min((v for v in counts if v != bg), key=lambda v: counts[v])
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != marker:
                continue
            for dr, dc in ((0,1),(1,0)):
                rr, cc = r+dr, c+dc
                while rr < h and cc < w and grid[rr][cc] != marker:
                    out[rr][cc] = 3
                    rr += dr
                    cc += dc
    return out
